//! Finite-dimensional quotients and truncations of graded algebras: the "finite-dimensional
//! linear algebra" equality strategy.
//!
//! The ambient algebra comes with an evaluator that writes every term in a basis of homogeneous
//! words (`Evaluator::graded_basis`), so each graded piece `A_d e(i)` (all words from the object
//! `i` of degree `d`) is a finite-dimensional space with known coordinates. A quotient by the
//! two-sided ideal generated by homogeneous elements `g` is computed piece by piece, from the lowest
//! degree up: the degree-`d` part of the ideal in `A e(i)` is spanned by the sandwiches
//! `ψ_u ∘ g ∘ ψ_w` of degree `d` and by `x_k ∘ v` and `v ∘ x_k` for `v` in lower parts of the ideal
//! (see [`Quotient::piece`]). Reducing modulo that span gives a normal form in the quotient, and the
//! basis words that are not pivots give a basis of the quotient piece. This needs the ambient
//! algebra to be generated by dots and crossings with both `{x^a ψ_w}` and `{ψ_w x^a}` spanning,
//! as for KLR algebras and the (odd) nilHecke algebras.
//!
//! Which quotient, and which degrees were computed, is printed on every result:
//!
//! * **Cyclotomic quotients** `R^Λ(ν) = R(ν) / ⟨x_1^{⟨h_{i_1}, Λ⟩} e(i)⟩` (context key `Lambda`).
//!   Degrees are computed up to `2(Λ, ν) − (ν, ν) − m`, with `m` the lowest degree of the ambient
//!   basis: `R^Λ(ν)` is graded symmetric with a symmetrizing form of degree `2(Λ, ν) − (ν, ν)`
//!   (Shan–Varagnolo–Vasserot, "On the center of quiver Hecke algebras"), so nothing lies above.
//! * **Dot caps** `A / ⟨x_k^N e(i)⟩` (context key `dotcap`): the words with every dot exponent
//!   below `N` span the quotient, which bounds its degrees.
//! * **Truncations** (context key `degcap`): only degrees up to the cap are computed. Without a
//!   quotient this is a truncation of the vector space, not an algebra.

use crate::context::Context;
use crate::elab::CTerm;
use crate::error::{Error, Result};
use crate::linalg::Reducer;
use crate::poly::{Poly, PolyRing};
use crate::pool::par_map;
use crate::rep::{Evaluator, PolyVector, Provenance, Strategy, basis_word};
use crate::ring::Ring;
use crate::term::{Object, Word};
use std::collections::{BTreeMap, HashMap};
use std::sync::{Arc, Mutex};

type PieceMap<R> = HashMap<(Object, i64), Arc<Piece<R>>>;
type Sandwiches<R> = Arc<Vec<(i64, CTerm<R>)>>;
type Summands<R> = Vec<(Word, Poly<<R as Ring>::Elem>)>;
/// Reduced coordinates of a term, by source object and degree, with the piece they refer to.
pub type Coordinates<R> = BTreeMap<(Object, i64), (Arc<Piece<R>>, Vec<Poly<<R as Ring>::Elem>>)>;

/// The strategy a session uses for a representation: the representation's own evaluator, or the
/// finite quotient or truncation the context names (`Lambda`, `dotcap`, `degcap`) computed
/// through it.
pub fn for_context<'a, R: Ring + 'a>(
    ctx: &'a Context<R>,
    eval: Box<dyn Evaluator<R> + 'a>,
) -> Result<Box<dyn Evaluator<R> + 'a>> {
    let s = &ctx.spec;
    if s.lambda.is_some() || s.dot_cap.is_some() || s.degree_cap.is_some() {
        Ok(Box::new(Quotient::from_context(ctx, eval)?))
    } else {
        Ok(eval)
    }
}

/// A homogeneous generator of the ideal, from `src` to `tgt`.
#[derive(Clone, Debug)]
pub struct IdealGen<R: Ring> {
    pub term: CTerm<R>,
    pub src: Object,
    pub tgt: Object,
    pub degree: i64,
}

/// One graded piece `A_d e(i)` of the ambient algebra with the ideal's part in it.
pub struct Piece<R: Ring> {
    /// The ambient basis, least preferred quotient representatives first.
    pub basis: Vec<Word>,
    index: HashMap<Word, usize>,
    /// The ideal's part, in coordinates.
    pub ideal: Reducer<PolyRing<R>>,
}

impl<R: Ring> Piece<R> {
    /// Indices of the basis words that form a basis of the quotient piece.
    pub fn quotient_basis(&self) -> Vec<usize> {
        self.ideal.free_columns()
    }
}

/// A finite-dimensional quotient or truncation of the algebra of a context.
pub struct Quotient<'a, R: Ring> {
    pub ctx: &'a Context<R>,
    pub eval: Box<dyn Evaluator<R> + 'a>,
    provenance: Provenance,
    pub gens: Vec<IdealGen<R>>,
    /// The highest degree computed, for each source object.
    caps: BTreeMap<Object, i64>,
    /// What the quotient is and how its degrees were bounded, one sentence each.
    pub description: Vec<String>,
    /// True when the degree bound comes only from a user's truncation.
    pub truncated: bool,
    /// For a cyclotomic quotient `R^Λ(ν)`, the degree `2(Λ, ν) − (ν, ν)` of its symmetrizing
    /// trace. The quotient is then a graded symmetric algebra (Shan–Varagnolo–Vasserot), so
    /// `dim e(t) A_d e(s) = dim e(s) A_{D−d} e(t)`: pieces above the middle degree stop reducing as
    /// soon as the ideal reaches the dimension this predicts, and pieces predicted to vanish are
    /// not reduced at all. Set to `None` to compute every piece in full.
    pub symmetric: Option<i64>,
    pieces: Mutex<PieceMap<R>>,
    /// The dot generator.
    dot: u16,
    sandwiches: Mutex<HashMap<Object, Sandwiches<R>>>,
    /// `x_k ∘ w` (flag true) and `w ∘ x_k` in normal form.
    dot_cache: Mutex<HashMap<(Word, usize, bool), CTerm<R>>>,
}

fn dot_generator<R: Ring>(ctx: &Context<R>) -> Result<u16> {
    ctx.pres
        .representations
        .iter()
        .find_map(|d| d.roles.get("dot"))
        .and_then(|n| ctx.pres.generator(n))
        .map(|g| g as u16)
        .ok_or_else(|| Error::precondition("this presentation names no dot generator"))
}

/// `x_k^e e(obj)` as a term.
fn dot_power<R: Ring>(
    ctx: &Context<R>,
    dot: u16,
    obj: &Object,
    k: usize,
    e: u32,
) -> Result<CTerm<R>> {
    let mut exps = vec![0i32; obj.len()];
    exps[k] = e as i32;
    // `basis_word` with no crossings needs no crossing generator; pass the dot twice.
    let w = basis_word(ctx, obj, &[], &exps, dot, dot, false)?;
    Ok(ctx.monomial_term(&w, ctx.coeff.one()))
}

impl<'a, R: Ring> Quotient<'a, R> {
    /// The quotient or truncation the context names (`Lambda`, `dotcap`, `degcap`).
    pub fn from_context(ctx: &'a Context<R>, eval: Box<dyn Evaluator<R> + 'a>) -> Result<Self> {
        let spec = &ctx.spec;
        if spec.lambda.is_none() && spec.dot_cap.is_none() && spec.degree_cap.is_none() {
            return Err(Error::precondition(
                "the algebra is infinite-dimensional: give Lambda, dotcap or degcap",
            ));
        }
        // The ideal's vectors have coefficients in the ground ring, so scalars may appear in the
        // terms being reduced as long as the ground ring is a field.
        if !ctx.base.is_field() {
            return Err(Error::precondition(format!(
                "quotients are computed over a field; the ground ring here is {}",
                spec.ring
            )));
        }
        if ctx.objects.is_empty() {
            return Err(Error::precondition("quotients need a weight nu"));
        }
        let inner = eval.provenance();
        let provenance = Provenance {
            strategy: Strategy::FiniteLinearAlgebra,
            method: format!("{} modulo the ideal", inner.method),
            certificate: inner.certificate.clone(),
        };
        let mut q = Quotient {
            ctx,
            eval,
            provenance,
            gens: vec![],
            caps: BTreeMap::new(),
            description: vec![],
            truncated: false,
            symmetric: None,
            pieces: Mutex::new(HashMap::new()),
            dot: dot_generator(ctx)?,
            sandwiches: Mutex::new(HashMap::new()),
            dot_cache: Mutex::new(HashMap::new()),
        };
        let lo = ctx
            .objects
            .iter()
            .map(|o| q.eval.min_degree(o))
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .min()
            .unwrap_or(0);
        let mut bound: Option<i64> = None;
        let mut per_object: BTreeMap<Object, i64> = BTreeMap::new();
        if let Some(l) = &spec.lambda {
            let lam = ctx.parse_weight(l)?;
            let dot = dot_generator(ctx)?;
            for obj in &ctx.objects {
                let e = lam[obj[0].colour as usize];
                q.push_gen(dot_power(ctx, dot, obj, 0, e)?)?;
            }
            let nu = ctx.weight.clone().unwrap_or_default();
            match &ctx.cartan {
                Some(cartan) => {
                    let n = nu.len();
                    let lam_nu: i64 = (0..n)
                        .map(|i| lam[i] as i64 * cartan.d[i] * nu[i] as i64)
                        .sum();
                    let nu_nu: i64 = (0..n)
                        .flat_map(|i| (0..n).map(move |j| (i, j)))
                        .map(|(i, j)| nu[i] as i64 * nu[j] as i64 * cartan.form(i, j))
                        .sum();
                    let top = 2 * lam_nu - nu_nu - lo;
                    bound = Some(top);
                    if spec.dot_cap.is_none() {
                        q.symmetric = Some(2 * lam_nu - nu_nu);
                    }
                    q.description.push(format!(
                "cyclotomic quotient by x_1^<h_(i_1), Lambda> e(i), Lambda = {l}; degrees up to \
                 {top} = 2(Lambda, nu) - (nu, nu) - ({lo}), above which R^Lambda(nu) vanishes \
                 (graded symmetric of degree 2(Lambda, nu) - (nu, nu))"
            ));
                }
                None => {
                    if spec.degree_cap.is_none() {
                        return Err(Error::precondition(
                            "no degree bound is known for this quotient without a Cartan datum: \
                             give degcap",
                        ));
                    }
                    q.description.push(format!(
                        "quotient by x_1^<h_(i_1), Lambda> e(i), Lambda = {l}"
                    ));
                }
            }
        }
        if let Some(cap) = spec.dot_cap {
            let dot = dot_generator(ctx)?;
            for obj in &ctx.objects {
                for k in 0..obj.len() {
                    q.push_gen(dot_power(ctx, dot, obj, k, cap)?)?;
                }
                let top = q.eval.max_degree_below_dot_cap(obj, cap)?;
                let e = per_object.entry(obj.clone()).or_insert(top);
                *e = (*e).min(top);
            }
            q.description.push(format!(
                "quotient by x_k^{cap} e(i) for every strand k; words with dot exponents below \
                 {cap} span it"
            ));
        }
        if let Some(cap) = spec.degree_cap {
            let tighter = bound.is_none_or(|b| cap < b) && per_object.values().all(|&b| cap < b);
            bound = Some(bound.map_or(cap, |b| b.min(cap)));
            if tighter {
                q.truncated = true;
                q.description
                    .push(format!("truncated: only degrees up to {cap} are computed"));
            }
        }
        for obj in &ctx.objects {
            let mut top = i64::MAX;
            if let Some(b) = bound {
                top = top.min(b);
            }
            if let Some(&b) = per_object.get(obj) {
                top = top.min(b);
            }
            q.caps.insert(obj.clone(), top);
        }
        Ok(q)
    }

    fn push_gen(&mut self, t: CTerm<R>) -> Result<()> {
        let Some((w, _)) = t.terms.first() else {
            return Ok(());
        };
        let src = w.source.clone();
        let tgt = self.ctx.target(w);
        let degree = self.ctx.word_degree(w);
        self.gens.push(IdealGen {
            term: t,
            src,
            tgt,
            degree,
        });
        Ok(())
    }

    /// The degrees computed for words starting at `src`: from the lowest degree of the ambient
    /// basis to the cap.
    pub fn window(&self, src: &Object) -> Result<(i64, i64)> {
        let lo = self.eval.min_degree(src)?;
        let hi = *self
            .caps
            .get(src)
            .ok_or_else(|| Error::invalid("no such object in this context"))?;
        Ok((lo, hi))
    }

    fn ambient_basis(&self, src: &Object, d: i64) -> Result<Vec<Word>> {
        let mut b = self.eval.graded_basis(src, d)?;
        // Longer words first: they become pivots, so quotient bases prefer short words.
        b.sort_by(|x, y| y.layers.len().cmp(&x.layers.len()).then_with(|| y.cmp(x)));
        Ok(b)
    }

    fn nf(&self, t: &CTerm<R>) -> Result<CTerm<R>> {
        self.eval.normal_form(t)
    }

    /// The elements `ψ_u ∘ g ∘ ψ_w` starting at `src`, for every generator `g` of the ideal and
    /// all crossing words `ψ_w` into `g`'s source and `ψ_u` out of its target, in normal form and
    /// with their degrees.
    fn sandwiches(&self, src: &Object) -> Result<Sandwiches<R>> {
        if let Some(z) = self.sandwiches.lock().unwrap().get(src) {
            return Ok(z.clone());
        }
        let ctx = self.ctx;
        let eval = self.eval.as_ref();
        let one = || ctx.coeff.one();
        let mut jobs = Vec::new();
        for g in &self.gens {
            for w in eval.crossing_words(src)? {
                if ctx.target(&w) != g.src {
                    continue;
                }
                let right = ctx.compose(&g.term, &ctx.monomial_term(&w, one()));
                for u in eval.crossing_words(&g.tgt)? {
                    jobs.push((u, right.clone()));
                }
            }
        }
        let done = par_map(&jobs, 8, |(u, right)| {
            eval.normal_form(&ctx.compose(&ctx.monomial_term(u, one()), right))
        });
        let mut out = Vec::new();
        for t in done {
            let t = t?;
            if let Some((w, _)) = t.terms.first() {
                out.push((ctx.word_degree(w), t));
            }
        }
        let out = Arc::new(out);
        self.sandwiches
            .lock()
            .unwrap()
            .insert(src.clone(), out.clone());
        Ok(out)
    }

    /// The degree of a dot on strand `k` of `obj`.
    fn dot_degree(&self, obj: &Object, k: usize) -> Result<i64> {
        let t = dot_power(self.ctx, self.dot, obj, k, 1)?;
        Ok(t.terms.first().map_or(0, |(w, _)| self.ctx.word_degree(w)))
    }

    /// Normal forms of `x_k ∘ w` (`top`) or `w ∘ x_k` for the given words, cached.
    fn dot_images(&self, keys: &[(Word, usize, bool)]) -> Result<()> {
        let missing: Vec<(Word, usize, bool)> = {
            let cache = self.dot_cache.lock().unwrap();
            let mut m: Vec<_> = keys
                .iter()
                .filter(|k| !cache.contains_key(*k))
                .cloned()
                .collect();
            m.sort();
            m.dedup();
            m
        };
        let ctx = self.ctx;
        let eval = self.eval.as_ref();
        let dot = self.dot;
        let done = par_map(&missing, 16, |(w, k, top)| -> Result<CTerm<R>> {
            let one = ctx.coeff.one();
            let word = ctx.monomial_term(w, one);
            let t = if *top {
                ctx.compose(&dot_power(ctx, dot, &ctx.target(w), *k, 1)?, &word)
            } else {
                ctx.compose(&word, &dot_power(ctx, dot, &w.source, *k, 1)?)
            };
            eval.normal_form(&t)
        });
        let mut cache = self.dot_cache.lock().unwrap();
        for (k, t) in missing.into_iter().zip(done) {
            cache.insert(k, t?);
        }
        Ok(())
    }

    /// The piece `A_d e(src)` with the ideal's part in it.
    ///
    /// The ideal generated by the `g` is spanned by the words `x^a ψ_u g ψ_w x^b`, since
    /// `{x^a ψ_u}` and `{ψ_w x^b}` both span the algebra. So its degree-`d` part is spanned by the
    /// sandwiches `ψ_u g ψ_w` of degree `d` and the products `x_k I` and `I x_k` with lower parts
    /// `I` of the ideal, which this computes recursively from the lowest degree.
    pub fn piece(&self, src: &Object, d: i64) -> Result<Arc<Piece<R>>> {
        if let Some(p) = self.pieces.lock().unwrap().get(&(src.clone(), d)) {
            return Ok(p.clone());
        }
        let (lo, hi) = self.window(src)?;
        if d > hi {
            return Err(Error::precondition(format!(
                "degree {d} is above the degrees computed here (up to {hi})"
            )));
        }
        let basis = if d < lo {
            vec![]
        } else {
            self.ambient_basis(src, d)?
        };
        let index: HashMap<Word, usize> = basis
            .iter()
            .cloned()
            .enumerate()
            .map(|(k, w)| (w, k))
            .collect();
        let mut piece = Piece {
            basis,
            index,
            ideal: Reducer::new(self.ctx.coeff.clone(), 0),
        };
        let mut ideal = Reducer::new(self.ctx.coeff.clone(), piece.basis.len());
        // The quotient dimension graded symmetry predicts, above the middle degree.
        let mut expected = None;
        if let Some(sym) = self.symmetric
            && 2 * d > sym
            && !piece.basis.is_empty()
        {
            let mut n = 0;
            for t in &self.ctx.objects {
                let dual = self.piece(t, sym - d)?;
                n += dual
                    .quotient_basis()
                    .into_iter()
                    .filter(|&k| self.ctx.target(&dual.basis[k]) == *src)
                    .count();
            }
            expected = Some(n.min(piece.basis.len()));
        }
        let goal = piece.basis.len() - expected.unwrap_or(0);
        if goal == piece.basis.len() && expected.is_some() {
            ideal = Reducer::full(self.ctx.coeff.clone(), goal);
        } else if !piece.basis.is_empty() {
            let full = |r: &Reducer<PolyRing<R>>| r.rank() >= goal;
            for (deg, z) in self.sandwiches(src)?.iter() {
                if *deg == d && !full(&ideal) {
                    ideal.insert(self.coords_in(&piece, z)?);
                }
            }
            // Products with a dot: each lower part of the ideal times x_k on either side.
            let n = src.len();
            let mut lower_degrees: Vec<i64> = Vec::new();
            for k in 0..n {
                lower_degrees.push(d - self.dot_degree(src, k)?);
            }
            for obj in &self.ctx.objects {
                for k in 0..n {
                    lower_degrees.push(d - self.dot_degree(obj, k)?);
                }
            }
            lower_degrees.sort();
            lower_degrees.dedup();
            for e in lower_degrees {
                if e < lo || e >= d || full(&ideal) {
                    continue;
                }
                let lower = self.piece(src, e)?;
                if lower.ideal.rank() == 0 {
                    continue;
                }
                let mut keys = Vec::new();
                let mut wanted = Vec::new();
                for v in lower.ideal.sparse_basis() {
                    let tgt = self.ctx.target(&lower.basis[v[0].0]);
                    for k in 0..n {
                        for top in [false, true] {
                            let obj = if top { &tgt } else { src };
                            if self.dot_degree(obj, k)? != d - e {
                                continue;
                            }
                            for (j, _) in v {
                                keys.push((lower.basis[*j].clone(), k, top));
                            }
                            wanted.push((v, k, top));
                        }
                    }
                }
                self.dot_images(&keys)?;
                let cache = self.dot_cache.lock().unwrap();
                for (v, k, top) in wanted {
                    if full(&ideal) {
                        break;
                    }
                    let mut acc = vec![self.ctx.coeff.zero(); piece.basis.len()];
                    for (j, c) in v {
                        let img = &cache[&(lower.basis[*j].clone(), k, top)];
                        for (w, a) in &img.terms {
                            let i = *piece.index.get(w).ok_or_else(|| {
                                Error::invalid("a normal-form word is not in the graded basis")
                            })?;
                            acc[i] = self.ctx.coeff.add(&acc[i], &self.ctx.coeff.mul(c, a));
                        }
                    }
                    ideal.insert(acc);
                }
            }
            if expected.is_some() && ideal.rank() < goal {
                return Err(Error::invalid(format!(
                    "internal: the quotient piece in degree {d} is larger than graded symmetry \
                     allows ({} > {})",
                    piece.basis.len() - ideal.rank(),
                    expected.unwrap_or(0)
                )));
            }
        }
        piece.ideal = ideal;
        let p = Arc::new(piece);
        self.pieces
            .lock()
            .unwrap()
            .insert((src.clone(), d), p.clone());
        Ok(p)
    }

    /// Coordinates of a normal form all of whose words lie in `piece`.
    fn coords_in(&self, piece: &Piece<R>, t: &CTerm<R>) -> Result<Vec<Poly<R::Elem>>> {
        let mut v = vec![self.ctx.coeff.zero(); piece.basis.len()];
        for (w, c) in &t.terms {
            let k = piece
                .index
                .get(w)
                .ok_or_else(|| Error::invalid("a normal-form word is not in the graded basis"))?;
            v[*k] = c.clone();
        }
        Ok(v)
    }

    /// The normal form split into homogeneous parts by source object and degree.
    fn split(&self, t: &CTerm<R>) -> Result<BTreeMap<(Object, i64), CTerm<R>>> {
        let n = self.nf(t)?;
        let mut parts: BTreeMap<(Object, i64), Summands<R>> = BTreeMap::new();
        for (w, c) in n.terms {
            let d = self.ctx.word_degree(&w);
            parts.entry((w.source.clone(), d)).or_default().push((w, c));
        }
        Ok(parts
            .into_iter()
            .map(|(k, v)| (k, self.ctx.normalize(v)))
            .collect())
    }

    /// Coordinates of a term in the quotient, by source object and degree: the reduced vector
    /// over the whole ambient basis of each piece (zero at the pivots).
    pub fn coordinates(&self, t: &CTerm<R>) -> Result<Coordinates<R>> {
        let mut out = BTreeMap::new();
        for ((src, d), part) in self.split(t)? {
            let p = self.piece(&src, d)?;
            let v = p.ideal.reduce(&self.coords_in(&p, &part)?);
            if v.iter().any(|c| !self.ctx.coeff.is_zero(c)) {
                out.insert((src, d), (p, v));
            }
        }
        Ok(out)
    }

    /// The normal form in the quotient: the ambient normal form reduced modulo the ideal, written
    /// in the quotient basis.
    pub fn reduce(&self, t: &CTerm<R>) -> Result<CTerm<R>> {
        let mut out = Vec::new();
        for (_, (p, v)) in self.coordinates(t)? {
            for (k, c) in v.into_iter().enumerate() {
                if !self.ctx.coeff.is_zero(&c) {
                    out.push((p.basis[k].clone(), c));
                }
            }
        }
        Ok(self.ctx.normalize(out))
    }

    pub fn is_zero(&self, t: &CTerm<R>) -> Result<bool> {
        Ok(self.coordinates(t)?.is_empty())
    }

    /// Dimensions of the quotient pieces `e(tgt) A_d e(src)` (or of `A_d e(src)` when `tgt` is
    /// `None`) over the computed degrees, nonzero ones only.
    pub fn graded_dimension(
        &self,
        src: &Object,
        tgt: Option<&Object>,
    ) -> Result<BTreeMap<i64, usize>> {
        let (lo, hi) = self.window(src)?;
        let mut out = BTreeMap::new();
        for d in lo..=hi {
            let p = self.piece(src, d)?;
            let n = p
                .quotient_basis()
                .into_iter()
                .filter(|&k| tgt.is_none_or(|t| self.ctx.target(&p.basis[k]) == *t))
                .count();
            if n > 0 {
                out.insert(d, n);
            }
        }
        Ok(out)
    }

    /// Basis of the quotient: `(degree, word)` for every computed degree and every object.
    pub fn basis(&self) -> Result<Vec<(i64, Word)>> {
        let mut out = Vec::new();
        for src in &self.ctx.objects {
            let (lo, hi) = self.window(src)?;
            for d in lo..=hi {
                let p = self.piece(src, d)?;
                for k in p.quotient_basis() {
                    out.push((d, p.basis[k].clone()));
                }
            }
        }
        Ok(out)
    }
}

impl<R: Ring> Evaluator<R> for Quotient<'_, R> {
    fn provenance(&self) -> &Provenance {
        &self.provenance
    }

    fn normal_form(&self, t: &CTerm<R>) -> Result<CTerm<R>> {
        self.reduce(t)
    }

    fn is_zero(&self, t: &CTerm<R>) -> Result<bool> {
        Quotient::is_zero(self, t)
    }

    fn act(&self, _t: &CTerm<R>, _obj: &Object, _f: &Poly<R::Elem>) -> Result<PolyVector<R::Elem>> {
        Err(Error::precondition(
            "a quotient does not act on polynomials: the polynomial representation is of the \
             ambient algebra",
        ))
    }

    fn poly_ring(&self, n: usize) -> PolyRing<R> {
        self.eval.poly_ring(n)
    }

    fn graded_basis(&self, src: &Object, degree: i64) -> Result<Vec<Word>> {
        let p = self.piece(src, degree)?;
        Ok(p.quotient_basis()
            .into_iter()
            .map(|k| p.basis[k].clone())
            .collect())
    }

    fn min_degree(&self, src: &Object) -> Result<i64> {
        self.eval.min_degree(src)
    }

    fn crossing_words(&self, src: &Object) -> Result<Vec<Word>> {
        self.eval.crossing_words(src)
    }

    fn notes(&self) -> Vec<String> {
        self.description.clone()
    }

    fn max_degree(&self, src: &Object) -> Result<Option<i64>> {
        Ok(Some(self.window(src)?.1))
    }

    fn complete(&self) -> bool {
        !self.truncated
    }
}
